CREATE TABLE IF NOT EXISTS counters(name TEXT PRIMARY KEY,value INTEGER NOT NULL);
INSERT OR IGNORE INTO counters(name,value) VALUES('filing',0);
CREATE TABLE IF NOT EXISTS templates(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,record_type TEXT NOT NULL,definition TEXT NOT NULL,active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS officers(id INTEGER PRIMARY KEY AUTOINCREMENT,first_name TEXT NOT NULL,last_name TEXT NOT NULL,rank TEXT,unit TEXT,division TEXT,discord_id TEXT,active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS records(id INTEGER PRIMARY KEY AUTOINCREMENT,filing_no TEXT UNIQUE NOT NULL,doc_no TEXT NOT NULL,template_id INTEGER NOT NULL,record_type TEXT NOT NULL,title TEXT NOT NULL,author TEXT NOT NULL,data TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(template_id) REFERENCES templates(id));
CREATE TABLE IF NOT EXISTS links(record_id INTEGER NOT NULL,linked_record_id INTEGER NOT NULL,PRIMARY KEY(record_id,linked_record_id));
INSERT OR IGNORE INTO templates(id,title,record_type,definition) VALUES(1,'SAST Daily Patrol Log','form','{"sections":[{"name":"Trooper Information","fields":[{"key":"name","label":"Name","type":"mention","required":true},{"key":"rank","label":"Rank","type":"text","size":"sm"},{"key":"unit","label":"Unit","type":"text","size":"sm"},{"key":"division","label":"Division","type":"text","size":"sm"},{"key":"date","label":"Date","type":"date","required":true},{"key":"shift","label":"Shift","type":"select","options":["Day","Evening","Night","Overnight"]},{"key":"start_time","label":"Start Time","type":"time"},{"key":"end_time","label":"End Time","type":"time"},{"key":"vehicle","label":"Vehicle/Unit Number","type":"text","size":"sm"}]},{"name":"Patrol Activity","type":"table","columns":[{"key":"time","label":"Time","size":"sm"},{"key":"location","label":"Location / Postal","size":"md"},{"key":"activity","label":"Activity / Call","size":"lg"},{"key":"action","label":"Action Taken","size":"lg"},{"key":"outcome","label":"Outcome","size":"md"}],"rows":12},{"name":"Linked Records","fields":[{"key":"linked","label":"Linked Reports / Forms","type":"record-links"},{"key":"other_numbers","label":"Other Report / Case Numbers","type":"textarea","size":"md"}]},{"name":"Daily Totals","type":"grid","fields":["traffic_stops","citations","warnings","arrests","pursuits","reports_completed","backup_calls","other_calls"]},{"name":"End-of-Shift Notes","fields":[{"key":"notes","label":"End-of-Shift Notes","type":"textarea","size":"xl"},{"key":"supervisor","label":"Supervisor / Signature","type":"mention"},{"key":"supervisor_date","label":"Supervisor Date","type":"date"},{"key":"equipment","label":"Equipment / Vehicle Issues","type":"textarea","size":"md"},{"key":"handoff","label":"Shift Handoff / Outstanding Items","type":"textarea","size":"md"}]}]}');